const KEY='nexus-portfolio-20261029-v1', TODAY='2026-10-29', MONTH='2026-10';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',log:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',check:'<path d="m5 12 4 4L19 6"/>',approve:'<path d="M9 4H6a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2h-3"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="m8 13 3 3 5-6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',chart:'<path d="M3 3v18h18M7 15l5-5 4 3 5-7"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 6 6 6-6 6"/>',left:'<path d="m15 6-6 6 6 6"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wallet:'<path d="M20 7V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h15V7H5a2 2 0 0 1 0-4"/><path d="M20 11h-6v6h6m-3-3h.01"/>',alert:'<path d="m12 3 10 18H2zM12 9v5m0 3v.01"/>',spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.01"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 11-2l3 3M4 16l3 3a7 7 0 0 0 11-2"/>',play:'<path d="m9 5 11 7-11 7z"/>',file:'<path d="M14 2H5v20h14V7zM14 2v6h5M8 12h8m-8 4h6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',code:'<path d="m8 5-7 7 7 7m8-14 7 7-7 7m-3-17-2 20"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14z"/>',print:'<path d="M6 9V3h12v6M6 18H3V9h18v9h-3M6 14h12v7H6z"/>'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.folder}</svg>`;
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number(v).toLocaleString('zh-CN',{maximumFractionDigits:1});
const money=v=>'¥'+Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const compact=v=>v>=10000?(v/10000).toFixed(2)+' 万':n(v);
const roleNames={BANK_MANAGER:'银行项目经理',VENDOR_MANAGER:'外包项目经理',NONE:'外包开发人员',SUPER_ADMIN:'系统管理员'};
const levelNames={LOW:'初级',MIDDLE:'中级',HIGH:'高级'};
const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
function seed(){
 const users=[{id:'b1',name:'林知远',login:'linzy',type:'BANK',role:'BANK_MANAGER'},{id:'v1',name:'陈嘉宁',login:'chenjn',type:'EXTERNAL',role:'VENDOR_MANAGER',company:'华辰科技',level:'HIGH',rate:400},{id:'u1',name:'吴晨',login:'wuchen',type:'EXTERNAL',role:'NONE',company:'华辰科技',level:'MIDDLE',rate:300},{id:'u2',name:'许宁',login:'xuning',type:'EXTERNAL',role:'NONE',company:'华辰科技',level:'HIGH',rate:400},{id:'u3',name:'周航',login:'zhouhang',type:'EXTERNAL',role:'NONE',company:'启明信息',level:'MIDDLE',rate:320},{id:'u4',name:'苏悦',login:'suyue',type:'EXTERNAL',role:'NONE',company:'启明信息',level:'HIGH',rate:450},{id:'u5',name:'沈星',login:'shenxing',type:'EXTERNAL',role:'NONE',company:'华辰科技',level:'LOW',rate:200},{id:'b2',name:'顾言',login:'guyan',type:'BANK',role:'BANK_MANAGER'},{id:'v2',name:'赵一帆',login:'zhaoyf',type:'EXTERNAL',role:'VENDOR_MANAGER',company:'启明信息',level:'HIGH',rate:450},{id:'admin',name:'系统管理员',login:'admin',type:'BANK',role:'SUPER_ADMIN'}].map((u,i)=>({...u,status:'ACTIVE',no:'EMP-'+String(i+1).padStart(3,'0')}));
 const projects=[{id:'p1',name:'零售业务协同平台',no:'PRD-2026-001',company:'华辰科技',bank:'b1',vendor:'v1',progress:72,due:'2026-11-03',status:'ACTIVE',paid:false,confirmedAt:null},{id:'p2',name:'数据质量核验工具',no:'PRD-2026-002',company:'华辰科技',bank:'b1',vendor:'v1',progress:86,due:'2026-10-26',status:'ACTIVE',paid:false,confirmedAt:null},{id:'p3',name:'运营报表查询优化',no:'PRD-2026-003',company:'启明信息',bank:'b2',vendor:'v2',progress:100,due:'2026-10-24',status:'COMPLETED',paid:true,confirmedAt:'2026-10-25 10:30',confirmedBy:'b2'},{id:'p4',name:'客户服务知识库',no:'PRD-2026-004',company:'华辰科技',bank:'b1',vendor:'v1',progress:12,due:'2026-12-15',status:'ACTIVE',paid:false,confirmedAt:null},{id:'p5',name:'移动端服务体验升级',no:'PRD-2026-005',company:'启明信息',bank:'b2',vendor:'v2',progress:64,due:'2026-11-10',status:'ACTIVE',paid:false,confirmedAt:null},{id:'p6',name:'业务指标可视化看板',no:'PRD-2026-006',company:'华辰科技',bank:'b1',vendor:'v1',progress:40,due:'2026-11-28',status:'ACTIVE',paid:false,confirmedAt:null}];
 const members=[['p1','u1',160,300],['p1','u2',160,400],['p2','u1',96,300],['p2','u5',72,200],['p3','u3',120,320],['p3','u4',120,450],['p4','u1',48,300],['p4','u2',32,400],['p5','u3',200,320],['p5','u4',160,450],['p6','u1',160,300],['p6','u5',160,200]].map(([project,user,hours,rate])=>({id:uid(),project,user,hours,rate,level:users.find(u=>u.id===user).level,status:'ACTIVE'}));
 const logs=[];const contents=['完成查询页面开发与交互细节调整。','联调数据接口，处理分页与加载异常。','梳理组件状态，完善表单校验及错误提示。','完成业务功能自测，修复边界条件问题。','整理联调记录，更新页面说明与操作文档。'];
 for(const [project,days,hours] of [['p1',18,8],['p2',14,8],['p3',12,8],['p5',15,7.5],['p6',8,6]]){const ms=members.filter(m=>m.project===project);for(let day=0;day<days;day++){for(let i=0;i<ms.length;i++){const date='2026-10-'+String((project==='p3'?25:29)-days+day).padStart(2,'0');const all=project==='p3';const monthly=all||day<days-3;const daily=monthly||day<days-1;logs.push({id:uid(),project,user:ms[i].user,date,hours,content:contents[(day+i)%contents.length],daily,monthly:monthly?'2026-10-26 09:30':null});}}}
 const attendance=[];for(const u of users.filter(u=>u.role==='NONE')){for(let d=1;d<=29;d++){const date='2026-10-'+String(d).padStart(2,'0');let hours=logs.filter(l=>l.user===u.id&&l.date===date).reduce((s,l)=>s+l.hours,0);if(u.id==='u1'&&d===10)hours-=2;if(u.id==='u3'&&d===12)hours-=1.5;attendance.push({user:u.id,date,hours:Math.max(0,hours)});}}
 return{version:1,users,projects,members,logs,attendance,activity:[]};
}
let db;let storageOk=true;try{const raw=localStorage.getItem(KEY);db=raw?JSON.parse(raw):seed();if(db.version!==1||!['projects','logs','members','users','attendance','activity'].every(k=>Array.isArray(db[k])))db=seed();}catch{db=seed();storageOk=false;}
let session={user:'b1',page:'dashboard',project:'p1',tab:'overview',query:'',company:'',status:'',month:MONTH,date:TODAY,approvalProject:'p1',selected:new Set(),logPage:1,projectPage:1,logUser:'',onlyOwn:false,checkStatus:'',draftMembers:[],editProject:null,editLog:null,guide:false,modalTrigger:null};
const $=s=>document.querySelector(s), user=()=>db.users.find(u=>u.id===session.user), person=id=>db.users.find(u=>u.id===id)||{name:'未知人员',company:'—'}, project=id=>db.projects.find(p=>p.id===id), member=(p,u)=>db.members.find(m=>m.project===p&&m.user===u), manager=()=>user().role!=='NONE';
const canEdit=p=>user().role==='SUPER_ADMIN'||p.bank===user().id||p.vendor===user().id;
const canBudget=p=>user().role==='SUPER_ADMIN'||p.bank===user().id;
const canMonthly=p=>user().role==='BANK_MANAGER'&&p.bank===user().id;
const canDaily=p=>user().role==='VENDOR_MANAGER'&&p.vendor===user().id;
const canPaid=p=>user().role==='SUPER_ADMIN'||canMonthly(p);
const stamp=()=>TODAY+' '+new Date().toLocaleTimeString('zh-CN',{hour12:false});
const total=(items,key)=>items.reduce((s,x)=>s+Number(x[key]||0),0);
const amount=l=>Math.round(l.hours*(member(l.project,l.user)?.rate||0)*100);
function aggregate(p){const ms=db.members.filter(m=>m.project===p.id),ls=db.logs.filter(l=>l.project===p.id),cs=ls.filter(l=>l.monthly),budgetC=ms.reduce((s,m)=>s+Math.round(m.hours*m.rate*100),0),actualC=ls.reduce((s,l)=>s+amount(l),0),confirmedC=cs.reduce((s,l)=>s+amount(l),0);return{members:ms,logs:ls,confirmed:cs,hours:total(ls,'hours'),confirmedHours:total(cs,'hours'),estimated:total(ms,'hours'),budget:budgetC/100,actual:actualC/100,confirmedAmount:confirmedC/100};}
function warnings(p){const a=aggregate(p),w=[];const days=Math.round((Date.parse(p.due+'T00:00:00Z')-Date.parse(TODAY+'T00:00:00Z'))/86400000);if(p.status!=='COMPLETED'&&p.progress<100){if(days<0)w.push({level:'red',title:'逾期未完成',text:`已逾期 ${-days} 天，当前进度 ${p.progress}%`});else if(days<=7&&p.progress<90)w.push({level:'amber',title:'临期进度不足',text:`距计划完成 ${days} 天，当前进度 ${p.progress}%`});else if(days<=14&&p.progress<80)w.push({level:'amber',title:'提前关注',text:`距计划完成 ${days} 天，进度低于 80%`});}for(const [est,con,label,unit] of [[a.estimated,a.confirmedHours,'工作量','小时'],[a.budget,a.confirmedAmount,'预算','元']]){if(!est){w.push({level:'gray',title:label==='预算'?'预算待完善':'预计投入待完善',text:'请完善项目成员预计投入'});continue;}if(con>est)w.push({level:'red',title:label+'超限',text:`已确认 ${n(con)} / 预计 ${n(est)} ${unit}，超出 ${n(con-est)} ${unit}`});else if(con/est>=.8&&p.progress<100)w.push({level:'amber',title:label+'接近上限',text:`已使用 ${(con/est*100).toFixed(1)}%，剩余 ${n(est-con)} ${unit}`});}if(a.budget>0&&a.actual>a.budget&&a.confirmedAmount<=a.budget)w.push({level:'amber',title:'未确认投入风险',text:`累计投入 ${money(a.actual)}，其中待确认 ${money(a.actual-a.confirmedAmount)}`});return w;}
function invalidate(p){p.confirmedAt=null;p.confirmedBy=null;}
function persist(note){$('#print-root').innerHTML='';if(note)db.activity.unshift({id:uid(),text:note,user:user().name,time:stamp()});db.activity=db.activity.slice(0,30);try{localStorage.setItem(KEY,JSON.stringify(db));storageOk=true;}catch{storageOk=false;}render();}
let toastTimer;function toast(msg,error=false){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}">${h(msg)}</div>`;toastTimer=setTimeout(()=>$('#toast-root').innerHTML='',4800);}
const btn=(label,action,cls='',ico='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const pill=(label,cls='')=>`<span class="pill ${cls}">${h(label)}</span>`;
const progress=p=>`<div class="progress-row"><div class="progress"><i style="width:${p.progress}%"></i></div>${p.progress}%</div>`;
const statusPill=p=>pill({ACTIVE:'进行中',COMPLETED:'已完成',DISABLED:'已暂停'}[p.status],p.status==='ACTIVE'?'':p.status==='COMPLETED'?'gray':'amber');
const option=(value,label,selected)=>`<option value="${h(value)}" ${String(value)===String(selected)?'selected':''}>${h(label)}</option>`;
function heading(title,desc,actions='',eyebrow='WORKSPACE / OVERVIEW'){return`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
const empty=(text='暂无符合条件的数据')=>`<div class="empty">${icon('folder')}<p>${h(text)}</p></div>`;
function pages(count,page,action,size=8){const max=Math.max(1,Math.ceil(count/size));return`<div class="table-footer"><span>共 ${count} 条记录 · 每页 ${size} 条</span><div class="pages"><button aria-label="上一页" data-action="${action}" data-page="${page-1}" ${page===1?'disabled':''}>‹</button>${Array.from({length:max},(_,i)=>`<button class="${page===i+1?'current':''}" aria-label="第 ${i+1} 页" data-action="${action}" data-page="${i+1}">${i+1}</button>`).join('')}<button aria-label="下一页" data-action="${action}" data-page="${page+1}" ${page>=max?'disabled':''}>›</button></div></div>`;}
function nav(page,projectId){session.page=page;if(projectId)session.project=projectId;session.query='';session.company='';session.status='';session.logPage=1;session.projectPage=1;session.selected.clear();if(page==='detail')session.tab='overview';if(page==='approval'){const eligible=db.projects.filter(p=>canMonthly(p)||canDaily(p));session.approvalProject=(eligible[0]||db.projects[0]).id;session.date=user().role==='VENDOR_MANAGER'?'2026-10-28':TODAY;session.month=MONTH;}closeModal();location.hash=page+(page==='detail'?'/'+session.project:'');render();window.scrollTo({top:0,behavior:'smooth'});}
function render(){const titles={dashboard:'项目总览',projects:'项目管理',detail:'项目详情',logs:'工作日志',approval:'审核确认',attendance:'考勤与核对',accounts:'人员管理',about:'关于作品'};const counts=db.logs.filter(l=>!l.monthly).length;const navButton=(page,label,ico,count='')=>`<button type="button" class="${session.page===page||(page==='projects'&&session.page==='detail')?'active':''}" data-action="nav" data-page="${page}">${icon(ico)}<span>${label}</span>${count?`<span class="count">${count}</span>`:''}</button>`;$('#app').innerHTML=`<div class="mobile-overlay" data-action="menu-close"></div><aside class="sidebar"><a class="brand" href="#dashboard" aria-label="NEXUS 首页"><div class="brand-mark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3"><path d="M5 18V6l14 12V6"/></svg></div><div><strong>NEXUS</strong><small>协作工时 · 项目管理</small></div></a><div class="nav-label">工作空间</div><nav class="nav" aria-label="主导航">${navButton('dashboard','项目总览','grid')}${navButton('projects','项目管理','folder')}${navButton('logs','工作日志','log')}${navButton('approval','审核确认','approve',counts)}</nav><div class="nav-label">资源管理</div><nav class="nav" aria-label="资源导航">${navButton('attendance','考勤与核对','calendar')}${navButton('accounts','人员管理','users')}</nav><div class="side-bottom"><nav class="nav">${navButton('about','关于作品','info')}</nav><div class="side-note"><strong>${icon('spark')} 让协作过程看得见</strong><p>切换角色，体验从填报到确认的完整协作流程。</p>${btn('一分钟体验','guide','','play')}</div><div class="copyright">NEXUS © 2026 · PORTFOLIO</div></div></aside><div class="shell"><header class="topbar"> <button class="mobile-menu" aria-label="展开导航" data-action="menu">${icon('menu')}</button><div class="breadcrumb">工作空间 ${icon('chevron')} <b>${titles[session.page]||'项目总览'}</b></div><div class="top-actions"><span class="date-label">2026 年 10 月 29 日 · 星期四</span>${btn('演示指南','guide','ghost small','play')}<div class="role-picker"><div class="avatar">${h(user().name.slice(-2))}</div><div><small>体验身份 · 可切换</small><select id="role-picker" aria-label="切换体验身份">${['b1','v1','u1','admin'].map(id=>option(id,person(id).name+' · '+roleNames[person(id).role],session.user)).join('')}</select></div></div></header><main class="main" id="main-content">${renderPage()}</main></div>`;}
function renderPage(){switch(session.page){case'projects':return renderProjects();case'detail':return renderDetail();case'logs':return renderLogs();case'approval':return renderApproval();case'attendance':return renderAttendance();case'accounts':return renderAccounts();case'about':return renderAbout();default:return renderDashboard();}}
function statsCards(items){return`<div class="stats">${items.map((x,i)=>`<div class="stat ${i===0?'featured':''}"><div class="stat-top">${x.label}<span class="stat-icon">${icon(x.icon)}</span></div><div class="stat-value">${x.value}<small>${x.unit||''}</small></div><div class="stat-foot"><span class="dot ${x.warn?'amber':''}"></span>${x.foot}</div></div>`).join('')}</div>`;}
function projectRows(ps){return ps.map((p,i)=>{const a=aggregate(p),ws=warnings(p);return`<tr><td><div class="project-title"><span class="project-icon ${['','blue','orange'][i%3]}">${icon('folder')}</span><div><button class="text-btn" data-action="detail" data-id="${p.id}"><strong>${h(p.name)}</strong></button><span class="subtext">${h(p.no)}</span></div></div></td><td>${h(p.company)}<span class="subtext">${h(person(p.bank).name)} / ${h(person(p.vendor).name)}</span></td><td>${progress(p)}</td><td>${n(a.hours)} <span class="subtext">预计 ${n(a.estimated)} h</span></td><td>${money(a.actual)}<span class="subtext">预算 ${money(a.budget)}</span></td><td>${ws.length?pill(ws[0].title,ws[0].level):statusPill(p)}</td><td><button class="text-btn" data-action="detail" data-id="${p.id}">查看 ${icon('chevron')}</button></td></tr>`;}).join('');}
const projectTable=ps=>`<div class="table-scroll"><table><thead><tr><th>项目名称 / 需求编号</th><th>合作公司 / 项目经理</th><th>项目进度</th><th>实际工时</th><th>累计投入</th><th>项目状态与风险</th><th>操作</th></tr></thead><tbody>${projectRows(ps)}</tbody></table></div>${!ps.length?empty():''}`;
function chartSvg(){const values=Array.from({length:7},(_,i)=>{const date='2026-10-'+(23+i);return total(db.logs.filter(l=>l.date===date),'hours');});const max=Math.max(16,...values)*1.25;const pts=values.map((v,i)=>[50+i*87,150-v/max*120]);const line=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');const cpts=values.map((v,i)=>[50+i*87,150-total(db.logs.filter(l=>l.date==='2026-10-'+(23+i)&&l.monthly),'hours')/max*120]);return`<svg class="chart" viewBox="0 0 620 185" role="img" aria-label="近七日日志填报工时和已确认工时，数据随演示操作更新"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#38987b" stop-opacity=".2"/><stop offset="1" stop-color="#38987b" stop-opacity=".01"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line class="chart-grid" x1="44" y1="${30+i*40}" x2="590" y2="${30+i*40}"/><text x="7" y="${34+i*40}">${n(max*(3-i)/3)}</text>`).join('')}<path d="${line} L572,150 L50,150 Z" fill="url(#chartFill)"/><path d="${cpts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ')}" fill="none" stroke="#bad7ca" stroke-width="2" stroke-dasharray="5 5"/><path d="${line}" fill="none" stroke="#368b6f" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="white" stroke="#368b6f" stroke-width="2"><title>10/${23+i}：${values[i]} 小时</title></circle><text x="${p[0]}" y="178" text-anchor="middle">10/${23+i}</text>`).join('')}</svg>`;}
function renderDashboard(){const as=db.projects.map(aggregate),hours=as.reduce((s,a)=>s+a.hours,0),actual=as.reduce((s,a)=>s+a.actual,0),confirmed=as.reduce((s,a)=>s+a.confirmedAmount,0),risks=db.projects.filter(p=>warnings(p).length),pending=db.logs.filter(l=>!l.monthly),daily=db.logs.filter(l=>!l.daily);const week=total(db.logs.filter(l=>l.date>='2026-10-23'&&l.date<=TODAY),'hours');return heading('项目总览','每一份投入都有记录，每一步协作都清晰可见。',`${manager()?btn('导出概览','export-dashboard','','download'):''}${manager()?btn('登记项目','create-project','primary','plus'):btn('填写日志','new-log','primary','plus')}`)+statsCards([{label:'进行中项目',value:db.projects.filter(p=>p.status==='ACTIVE').length,unit:'个',icon:'folder',foot:`共 ${db.projects.length} 个项目 · ${db.projects.filter(p=>p.status==='COMPLETED').length} 个已完成`},{label:'累计实际工时',value:n(hours),unit:'小时',icon:'clock',foot:`已月度确认 ${n(as.reduce((s,a)=>s+a.confirmedHours,0))} 小时`},{label:'累计投入金额',value:compact(actual),unit:'元',icon:'wallet',foot:`待月度确认 ${money(actual-confirmed)}`},{label:'需要关注的项目',value:risks.length,unit:'个',icon:'alert',foot:`${db.projects.filter(p=>warnings(p).some(w=>w.level==='red')).length} 个项目存在超限或逾期风险`,warn:true}])+`<div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>工时投入趋势</h2><p>记录团队的每一份投入</p></div><span class="period">10.23 — 10.29</span></div><div class="chart-summary"><div><strong>${n(week)}</strong><small>小时 / 近 7 天</small></div><div class="chart-legend"><span><i class="legend-box"></i>实际工时</span><span><i class="legend-box light"></i>已确认工时</span></div></div>${chartSvg()}</section><section class="panel"><div class="panel-head"><h2>协作待办</h2><span class="task-total">全量业务概况</span></div><div class="todo-list"><div class="todo"><span class="todo-symbol">${icon('log')}</span><div class="todo-content"><strong>${daily.length} 条日志待日常确认</strong><small>外包项目经理核对工作内容与工时</small></div><button data-action="go-daily" aria-label="查看日常确认">${icon('chevron')}</button></div><div class="todo"><span class="todo-symbol green">${icon('approve')}</span><div class="todo-content"><strong>${pending.length} 条日志待月度确认</strong><small>日常确认后，由银行项目经理确认</small></div><button data-action="nav" data-page="approval" aria-label="查看月度确认">${icon('chevron')}</button></div><div class="todo"><span class="todo-symbol red">${icon('alert')}</span><div class="todo-content"><strong>${risks.length} 个项目需要关注</strong><small>及时查看进度、工时与预算风险</small></div><button data-action="risk-projects" aria-label="查看风险项目">${icon('chevron')}</button></div></div></section></div><section class="panel"><div class="panel-head"><div><h2>项目动态 <span class="task-total">${db.projects.length}</span></h2><p>连接进度、工时与预算，掌握项目全貌</p></div><div class="table-tools"><button class="text-btn" data-action="nav" data-page="projects">全部项目 ${icon('arrow')}</button></div></div>${projectTable(db.projects.slice(0,5))}<div class="table-footer"><span>展示最近的 ${Math.min(5,db.projects.length)} 个项目 · 金额单位：元</span><span>数据随演示操作实时更新</span></div></section><div class="insight-banner">${icon('spark')}<div><strong>不止于记录，更关注协作的完整过程</strong><p>试着填报一条日志，再切换经理身份完成确认，看看首页如何变化。</p></div>${btn('开始体验','guide','ghost small','arrow')}</div>${footer()}`;}
function footer(){return`<div class="bottom-note"><span>${icon(storageOk?'lock':'alert')}${storageOk?'演示数据仅保存在当前浏览器，可随时重置':'当前浏览器无法持久保存，关闭页面后可能恢复样例'}</span><span>示例日期 2026.10.29 · 纯前端交互原型</span></div>`;}
function filteredProjects(){return db.projects.filter(p=>(!session.query||[p.name,p.no,person(p.bank).name,person(p.vendor).name].join(' ').toLowerCase().includes(session.query.toLowerCase()))&&(!session.company||p.company===session.company)&&(!session.status||(session.status==='risk'?warnings(p).length:p.status===session.status)));}
function renderProjects(){const ps=filteredProjects();return heading('项目管理','从项目登记到工作量确认，在一个空间内跟进。',`${manager()?btn('导出 CSV','export-projects','','download')+btn('登记项目','create-project','primary','plus'):''}`,'WORKSPACE / PROJECTS')+`<section class="panel"><form class="filters" id="project-filter"><div class="field"><label for="project-query">项目 / 编号 / 经理</label><input id="project-query" name="query" value="${h(session.query)}" placeholder="搜索项目名称、需求编号或经理"></div><div class="field"><label for="company-filter">合作公司</label><select id="company-filter" name="company">${option('','全部公司',session.company)}${[...new Set(db.projects.map(p=>p.company))].map(c=>option(c,c,session.company)).join('')}</select></div><div class="field"><label for="status-filter">项目状态</label><select id="status-filter" name="status">${[['','全部项目'],['ACTIVE','进行中'],['COMPLETED','已完成'],['DISABLED','已暂停'],['risk','存在预警']].map(([v,l])=>option(v,l,session.status)).join('')}</select></div><button class="btn primary" type="submit">${icon('search')}查询</button>${btn('重置','reset-filter')}</form><div class="panel-head"><h2>项目列表 <span class="task-total">${ps.length}</span></h2><span class="screenshot-label">包含全部项目，编辑权限随身份变化</span></div>${projectTable(ps.slice((session.projectPage-1)*8,session.projectPage*8))}${pages(ps.length,session.projectPage,'project-page')}</section>${footer()}`;}
function warnList(p){const ws=warnings(p);return ws.length?ws.map(w=>`<div class="warning-item"><strong>${pill(w.title,w.level)}</strong><p>${h(w.text)}</p></div>`).join(''):`<div class="empty" style="padding:28px 0">${icon('check')}<p>当前暂无预警，项目运行平稳</p></div>`;}
function detailKey(p){return`<dl class="key-values"><div><dt>需求编号</dt><dd>${h(p.no)}</dd></div><div><dt>合作公司</dt><dd>${h(p.company)}</dd></div><div><dt>银行项目经理</dt><dd>${h(person(p.bank).name)}</dd></div><div><dt>外包项目经理</dt><dd>${h(person(p.vendor).name)}</dd></div><div><dt>计划完成日期</dt><dd>${h(p.due)}</dd></div><div><dt>付款状态 / 整体确认</dt><dd>${p.paid?'已付款':'未付款'} · ${p.confirmedAt?'已整体确认':'待整体确认'}</dd></div></dl>`;}
function meter(label,used,est,unit){const rate=est?used/est*100:null;return`<div class="meter-row"><span>${label}</span><b>${unit==='元'?money(used):n(used)} <span class="subtext" style="display:inline">/ ${unit==='元'?money(est):n(est)+' h'}</span></b></div><div class="wide-meter ${rate>100?'red':''}"><i style="width:${Math.min(100,rate||0)}%"></i></div><div class="annotation">${rate===null?'预计投入待完善':`已确认使用率 ${rate.toFixed(1)}%`}</div>`;}
function renderDetail(){const p=project(session.project);if(!p)return empty('项目不存在');const a=aggregate(p);let content='';if(session.tab==='overview'){content=`<div class="detail-grid section-gap"><section class="panel"><div class="panel-head"><h2>项目概况</h2>${statusPill(p)}</div><div class="panel-body">${detailKey(p)}<div class="meter-row"><span>项目进度</span><b>${p.progress}%</b></div><div class="wide-meter"><i style="width:${p.progress}%"></i></div>${meter('已确认工时 / 预计工时',a.confirmedHours,a.estimated,'小时')}${meter('已确认金额 / 预算金额',a.confirmedAmount,a.budget,'元')}<p class="annotation">使用率按已月度确认数据计算；全部未确认投入仍计入累计实际值。</p></div></section><section class="panel"><div class="panel-head"><h2>${icon('alert')} 风险关注</h2><span class="task-total">${warnings(p).length} 项</span></div><div class="panel-body">${warnList(p)}</div></section></div><section class="panel section-gap"><div class="panel-head"><h2>协作进度</h2><button class="text-btn" data-action="detail-tab" data-tab="settlement">查看整体确认 ${icon('arrow')}</button></div><div class="panel-body">${steps(p)}</div></section>`;}else if(session.tab==='members'){content=`<section class="panel section-gap"><div class="panel-head"><h2>成员与预算 <span class="task-total">${a.members.length} 人</span></h2>${canBudget(p)?btn('维护成员','edit-project','','edit',`data-id="${p.id}"`):''}</div><div class="panel-body"><div class="info-strip">${icon('lock')}项目单价用于预算和实际金额计算。产生日志后锁定；移除成员保留历史投入和预算。</div></div><div class="table-scroll"><table><thead><tr><th>项目成员</th><th>约定等级</th><th>预计投入</th><th>项目单价</th><th>预算金额</th><th>实际投入</th><th>参与状态</th></tr></thead><tbody>${a.members.map(m=>{const ls=a.logs.filter(l=>l.user===m.user);return`<tr><td>${h(person(m.user).name)}<span class="subtext">${h(person(m.user).no)}</span></td><td>${levelNames[m.level]}</td><td>${n(m.hours)} h</td><td>${money(m.rate)} / h ${ls.length?icon('lock'):''}</td><td>${money(m.hours*m.rate)}</td><td>${n(total(ls,'hours'))} h</td><td>${pill(m.status==='ACTIVE'?'参与中':'已移除',m.status==='ACTIVE'?'':'gray')}</td></tr>`;}).join('')}</tbody></table></div>${!a.members.length?empty('暂未添加成员'):''}</section>`;}else if(session.tab==='logs'){content=`<section class="panel section-gap"><div class="panel-head"><h2>项目工作日志</h2>${manager()?btn('导出 CSV','export-detail-logs','','download'):''}</div>${logTable(a.logs.slice().sort((x,y)=>y.date.localeCompare(x.date)),false)}<div class="table-footer"><span>共 ${a.logs.length} 条 · ${n(a.hours)} 小时</span><span>月度已确认 ${a.confirmed.length} 条</span></div></section>`;}else content=renderSettlement(p);return heading(h(p.name),`${h(p.no)} · ${h(p.company)} · 计划完成 ${h(p.due)}`,`${btn('返回列表','nav','','left','data-page="projects"')}${canEdit(p)?btn('修改项目','edit-project','','edit',`data-id="${p.id}"`):''}${manager()?btn('业务数据 CSV','export-detail','primary','download'):''}`,'WORKSPACE / PROJECT DETAILS')+statsCards([{label:'累计实际工时',value:n(a.hours),unit:'小时',icon:'clock',foot:`预计投入 ${n(a.estimated)} 小时`},{label:'已确认工时',value:n(a.confirmedHours),unit:'小时',icon:'approve',foot:`待确认 ${n(a.hours-a.confirmedHours)} 小时`},{label:'累计投入金额',value:compact(a.actual),unit:'元',icon:'wallet',foot:`预算金额 ${money(a.budget)}`},{label:'已确认金额',value:compact(a.confirmedAmount),unit:'元',icon:'chart',foot:`待确认 ${money(a.actual-a.confirmedAmount)}`}])+`<div class="panel"><div class="tabs" role="tablist" aria-label="项目详情">${[['overview','项目概况'],['members','成员与预算'],['logs','工作日志'],['settlement','整体确认与报告']].map(([v,l])=>`<button role="tab" aria-selected="${session.tab===v}" class="${session.tab===v?'active':''}" data-action="detail-tab" data-tab="${v}">${l}</button>`).join('')}</div></div>${content}${footer()}`;}
function steps(p){const ls=aggregate(p).logs;return`<div class="step-list">${[['项目登记',true],['日志填报',!!ls.length],['日常确认',ls.length&&ls.every(l=>l.daily)],['月度确认',ls.length&&ls.every(l=>l.monthly)],['整体确认',!!p.confirmedAt]].map(([label,done],i)=>`<div class="step ${done?'done':''}"><div class="step-circle">${done?'✓':i+1}</div>${label}</div>`).join('')}</div>`;}
function confirmationBlock(p){const a=aggregate(p);if(!a.logs.length)return'项目尚无日志，请先填报';if(a.logs.some(l=>!l.monthly))return`还有 ${a.logs.filter(l=>!l.monthly).length} 条日志未完成月度确认`;if(a.logs.some(l=>!member(p.id,l.user)||!(member(p.id,l.user).rate>0)))return'成员计价数据不完整';return'';}
function renderSettlement(p){const a=aggregate(p),block=confirmationBlock(p),ws=warnings(p);return`<div class="detail-grid section-gap"><section class="panel"><div class="panel-head"><h2>项目整体工作量确认</h2>${pill(p.confirmedAt?'已确认':'待确认',p.confirmedAt?'':'amber')}</div><div class="panel-body">${steps(p)}<div class="info-strip ${block?'amber':''}">${icon(block?'info':'check')}${p.confirmedAt?`由 ${h(person(p.confirmedBy).name)} 于 ${h(p.confirmedAt)} 确认`:(block||'全部日志已月度确认，可由本项目银行经理复核后执行整体确认。')}</div><dl class="key-values"><div><dt>项目实际工时</dt><dd>${n(a.hours)} 小时</dd></div><div><dt>累计实际金额</dt><dd>${money(a.actual)}</dd></div><div><dt>工时差异（实际 − 预计）</dt><dd>${n(a.hours-a.estimated)} 小时</dd></div><div><dt>金额差异（实际 − 预算）</dt><dd>${money(a.actual-a.budget)}</dd></div></dl><div class="actions">${canMonthly(p)?btn('确认整体工作量','overall-confirm','primary','approve',`data-id="${p.id}" ${block||p.confirmedAt?'disabled':''}`):''}${manager()?btn('项目报告预览','report','','file',`data-id="${p.id}" ${!p.confirmedAt?'disabled':''}`):''}</div><p class="annotation">整体确认仅限本项目银行经理。新增或修改日志、预算或相关考勤会使确认失效。报告为可打印预览。</p></div></section><section class="panel"><div class="panel-head"><h2>付款与复核提示</h2>${pill(p.paid?'已付款':'未付款',p.paid?'':'gray')}</div><div class="panel-body"><p class="note-paragraph">付款状态独立维护，不随月度确认、整体确认或报告导出自动变化。</p>${canPaid(p)?btn(p.paid?'标记为未付款':'标记为已付款','toggle-paid','','wallet',`data-id="${p.id}"`):`<div class="info-strip">${icon('lock')}仅本项目银行经理或管理员可维护付款状态。</div>`}<div class="section-gap">${warnList(p)}</div>${attendanceWarnings(p).length?`<div class="info-strip amber section-gap">${icon('alert')}${attendanceWarnings(p).length} 位成员存在月度考勤差异或考勤缺失，请复核后确认。</div>`:''}<p class="annotation">考勤差异与超预算会明确提示，复核后仍可确认。</p></div></section></div>`;}
function filteredLogs(){return db.logs.filter(l=>(!session.query||[project(l.project)?.name,person(l.user).name,l.content].join(' ').toLowerCase().includes(session.query.toLowerCase()))&&(!session.month||l.date.startsWith(session.month))&&(!session.onlyOwn||l.user===user().id)&&(!session.logUser||l.user===session.logUser)).sort((a,b)=>b.date.localeCompare(a.date));}
function logTable(ls,editable=true,selectable=false){return`<div class="table-scroll"><table><thead><tr>${selectable?`<th class="check-cell"><label title="选择当前范围全部待日常确认日志"><input type="checkbox" id="select-all" aria-label="全选待日常确认日志" ${ls.some(l=>!l.daily)&&ls.filter(l=>!l.daily).every(l=>session.selected.has(l.id))?'checked':''}></label></th>`:''}<th>日期 / 项目</th><th>填报人</th><th>工作内容</th><th>耗费工时</th><th>计算金额</th><th>日常确认</th><th>月度确认</th>${editable?'<th>操作</th>':''}</tr></thead><tbody>${ls.slice((session.logPage-1)*8,session.logPage*8).map(l=>`<tr>${selectable?`<td class="check-cell"><input type="checkbox" aria-label="选择 ${h(person(l.user).name)} ${h(l.date)} 日志" data-log-select="${l.id}" ${l.daily?'disabled':''} ${session.selected.has(l.id)?'checked':''}></td>`:''}<td>${h(l.date)}<span class="subtext">${h(project(l.project)?.name)}</span></td><td>${h(person(l.user).name)}</td><td><div class="log-content">${h(l.content)}</div></td><td>${n(l.hours)} h</td><td>${money(amount(l)/100)}</td><td>${pill(l.daily?'已确认':'待确认',l.daily?'':'amber')}</td><td>${pill(l.monthly?'已确认':'待确认',l.monthly?'':'gray')}</td>${editable?`<td>${l.user===user().id?`<button class="text-btn" data-action="edit-log" data-id="${l.id}">修改</button>`:'<span class="subtext">仅本人可修改</span>'}</td>`:''}</tr>`).join('')}</tbody></table></div>${!ls.length?empty('当前范围暂无日志，试试其他条件'):''}${ls.length>8?pages(ls.length,session.logPage,'log-page'):''}`;}
function renderLogs(){const ls=filteredLogs(),own=user().type==='EXTERNAL';return heading('工作日志','让工作被准确记录，让协作有据可循。',`${manager()?btn('导出 CSV','export-logs','','download'):''}${own?btn('填写日志','new-log','primary','plus'):''}`,'WORKSPACE / WORK LOGS')+`<section class="panel"><form class="filters" id="log-filter"><div class="field"><label for="log-query">项目 / 人员 / 工作内容</label><input id="log-query" name="query" value="${h(session.query)}" placeholder="输入关键词"></div><div class="field"><label for="log-month">日志月份</label><input type="month" id="log-month" name="month" value="${h(session.month)}"></div><div class="field"><label for="log-scope">查看范围</label><select id="log-scope" name="scope">${option('all','全部人员',session.onlyOwn?'own':'all')}${option('own','仅看本人',session.onlyOwn?'own':'all')}</select></div><button class="btn primary" type="submit">${icon('search')}查询</button>${btn('重置','reset-log-filter')}</form><div class="mini-summary"><div><span>范围内日志</span><strong>${ls.length}<small>条</small></strong></div><div><span>实际工时合计</span><strong>${n(total(ls,'hours'))}<small>小时</small></strong></div><div><span>实际金额合计</span><strong>${compact(ls.reduce((s,l)=>s+amount(l)/100,0))}<small>元</small></strong></div></div><div class="panel-head"><h2>日志明细</h2><span class="screenshot-label">所有角色可查看 · 仅原填报人可修改</span></div>${logTable(ls)}<div class="table-footer"><span>工时按 0.5 小时填写，金额使用项目约定单价计算</span><span>修改后需重新确认</span></div></section>${footer()}`;}
function approvalScope(){const p=project(session.approvalProject)||db.projects[0];return db.logs.filter(l=>l.project===p.id&&(canDaily(p)?l.date===session.date:l.date.startsWith(session.month))).sort((a,b)=>b.date.localeCompare(a.date));}
function renderApproval(){const p=project(session.approvalProject)||db.projects[0],daily=canDaily(p),monthly=canMonthly(p),ls=approvalScope(),pending=ls.filter(l=>daily?!l.daily:!l.monthly),selected=ls.filter(l=>session.selected.has(l.id)&&!l.daily),blockMonthly=ls.some(l=>!l.daily);return heading('审核确认',daily?'核对当日工作内容和投入工时，完成项目日常确认。':monthly?'核对项目当月全部日志、工时与金额，完成月度确认。':'查看全量日志确认情况；操作权限属于对应的项目经理。',manager()?btn('导出 CSV','export-approval','','download'):'','WORKSPACE / APPROVALS')+`<section class="panel"><form class="filters" id="approval-filter"><div class="field" style="max-width:300px"><label for="approval-project">项目</label><select id="approval-project" name="project">${db.projects.map(p=>option(p.id,p.name+(canMonthly(p)||canDaily(p)?' · 我负责的':''),session.approvalProject)).join('')}</select></div><div class="field"><label for="approval-date">${daily?'日志日期':'日志月份'}</label><input id="approval-date" name="range" type="${daily?'date':'month'}" value="${h(daily?session.date:session.month)}"></div><button class="btn primary" type="submit">${icon('search')}查询</button></form><div class="mini-summary"><div><span>本次查询范围</span><strong>${ls.length}<small>条日志</small></strong></div><div><span>${daily?'待日常确认工时':'待月度确认工时'}</span><strong>${n(total(pending,'hours'))}<small>小时</small></strong></div><div><span>待确认金额</span><strong>${compact(pending.reduce((s,l)=>s+amount(l)/100,0))}<small>元</small></strong></div></div><div class="panel-head"><h2>${daily?'日常确认':monthly?'月度确认':'确认记录'}</h2>${pill(daily?'外包经理操作':monthly?'银行经理操作':'当前只读',daily||monthly?'':'gray')}</div><div class="panel-body" style="padding-bottom:0">${daily?`<div class="info-strip">${icon('info')}勾选要确认的日志，可跨页选择。已确认记录不重复处理。</div>`:monthly?`<div class="info-strip ${blockMonthly?'amber':''}">${icon(blockMonthly?'alert':'info')}${blockMonthly?'当前范围仍有日志未完成日常确认，请先由外包经理确认。':'月度确认覆盖本项目当月全部待确认日志，包含所有分页。'}</div>`:`<div class="info-strip">${icon('lock')}可查看此项目的记录，日常和月度确认仅由项目登记的对应经理执行。</div>`}</div>${logTable(ls,false,daily)}<div class="approval-foot"><p>${daily?`已选 <strong>${selected.length}</strong> 条 · 合计 <strong>${n(total(selected,'hours'))}</strong> 小时`:`共 <strong>${pending.length}</strong> 条待月度确认 · ${n(total(pending,'hours'))} 小时`}</p>${daily?btn('确认所选日志','daily-confirm','primary','check',!selected.length?'disabled':''):monthly?btn('确认本月日志','monthly-confirm','primary','approve',blockMonthly||!pending.length?'disabled':''):''}</div></section>${footer()}`;}
function checks(month=MONTH){const relevant=db.users.filter(u=>u.type==='EXTERNAL'&&(db.logs.some(l=>l.user===u.id&&l.date.startsWith(month))||db.attendance.some(a=>a.user===u.id&&a.date.startsWith(month))));return relevant.map(u=>{const ls=db.logs.filter(l=>l.user===u.id&&l.date.startsWith(month)),as=db.attendance.filter(a=>a.user===u.id&&a.date.startsWith(month)),hours=total(ls,'hours'),attendance=total(as,'hours'),missing=[...new Set(ls.map(l=>l.date))].some(date=>!as.some(a=>a.date===date)),diff=hours-attendance;return{user:u.id,hours,attendance,diff,missing,warning:missing||Math.abs(diff)>.001,projects:[...new Set(ls.map(l=>l.project))]};});}
function attendanceWarnings(p){const ids=new Set(aggregate(p).members.map(m=>m.user));const months=new Set(aggregate(p).logs.map(l=>l.date.slice(0,7)));return[...months].flatMap(month=>checks(month).filter(c=>ids.has(c.user)&&c.projects.includes(p.id)&&c.warning));}
function renderAttendance(){let cs=checks(session.month);if(session.query)cs=cs.filter(c=>[person(c.user).name,person(c.user).company].join(' ').includes(session.query));if(session.checkStatus)cs=cs.filter(c=>session.checkStatus==='warning'?c.warning:!c.warning);const risk=cs.filter(c=>c.warning).length;return heading('考勤与核对','跨项目汇总人员月度工时，对照有效考勤，发现投入差异。',`${manager()?btn('导出核对 CSV','export-attendance','','download'):''}${user().role==='SUPER_ADMIN'?btn('导入考勤 CSV','import-attendance','primary','upload'):''}`,'RESOURCES / ATTENDANCE')+statsCards([{label:'本次核对人员',value:cs.length,unit:'人',icon:'users',foot:'按人员与月份汇总跨项目日志'},{label:'月度日志工时',value:n(total(cs,'hours')),unit:'小时',icon:'log',foot:'包含全部项目，不重复计算人员'},{label:'有效考勤工时',value:n(total(cs,'attendance')),unit:'小时',icon:'calendar',foot:'来自管理员导入的日考勤记录'},{label:'待复核人员',value:risk,unit:'人',icon:'alert',foot:'考勤缺失或日志工时存在差异',warn:true}])+`<section class="panel"><form class="filters" id="attendance-filter"><div class="field"><label for="check-query">人员 / 公司</label><input id="check-query" name="query" value="${h(session.query)}" placeholder="搜索人员或公司"></div><div class="field"><label for="check-month">核对月份</label><input id="check-month" name="month" type="month" value="${h(session.month)}"></div><div class="field"><label for="check-status">核对状态</label><select id="check-status" name="status">${option('','全部状态',session.checkStatus)}${option('pass','核对通过',session.checkStatus)}${option('warning','需要复核',session.checkStatus)}</select></div><button class="btn primary" type="submit">查询</button></form><div class="panel-head"><h2>月度工时核对</h2><span class="screenshot-label">差值 = 日志工时 − 有效考勤工时</span></div><div class="table-scroll"><table><thead><tr><th>人员 / 公司</th><th>参与项目</th><th>月度日志工时</th><th>有效考勤工时</th><th>工时差值</th><th>核对结果</th><th>操作</th></tr></thead><tbody>${cs.map(c=>`<tr><td>${h(person(c.user).name)}<span class="subtext">${h(person(c.user).company)}</span></td><td>${c.projects.length} 个</td><td>${n(c.hours)} h</td><td>${n(c.attendance)} h</td><td class="${c.warning?'alert-count':''}">${c.diff>0?'+':''}${n(c.diff)} h</td><td>${pill(c.missing?'考勤缺失':c.warning?'工时差异':'核对通过',c.warning?'amber':'')}</td><td><button class="text-btn" data-action="check-detail" data-id="${c.user}">查看明细</button></td></tr>`).join('')}</tbody></table></div>${!cs.length?empty('本月暂无考勤与日志数据'):''}<div class="table-footer"><span>考勤调整不直接修改日志工时或金额</span><span>相关项目整体确认会失效</span></div></section><div class="info-strip section-gap">${icon('info')}原型提供 CSV 导入与导出；生产方案中的 Excel 上传、服务端校验与固定 Word 模板报告待工程接入。</div>${footer()}`;}
function renderAccounts(){return heading('人员管理','集中查看人员、角色和默认单价，明确协作边界。',user().role==='SUPER_ADMIN'?btn('新增演示人员','new-user','primary','plus'):'','RESOURCES / PEOPLE')+`<section class="panel"><div class="panel-head"><h2>团队成员 <span class="task-total">${db.users.length}</span></h2>${pill(user().role==='SUPER_ADMIN'?'管理员可维护':'当前只读',user().role==='SUPER_ADMIN'?'':'gray')}</div><div class="table-scroll"><table><thead><tr><th>姓名 / 人员编号</th><th>公司 / 用户类型</th><th>管理角色</th><th>等级</th><th>默认单价</th><th>账号状态</th><th>操作</th></tr></thead><tbody>${db.users.map(u=>`<tr><td>${h(u.name)}<span class="subtext">${h(u.no)}</span></td><td>${h(u.company||'银行内部')}<span class="subtext">${u.type==='BANK'?'行员':'外包人员'}</span></td><td>${roleNames[u.role]}</td><td>${levelNames[u.level]||'—'}</td><td>${u.rate?money(u.rate)+' / h':'—'}</td><td>${pill(u.status==='ACTIVE'?'启用':'停用',u.status==='ACTIVE'?'':'gray')}</td><td>${user().role==='SUPER_ADMIN'&&u.id!=='admin'?`<button class="text-btn" data-action="edit-user" data-id="${u.id}">维护</button>`:'<span class="subtext">—</span>'}</td></tr>`).join('')}</tbody></table></div></section><div class="info-strip section-gap">${icon('info')}账号默认单价仅初始化新项目成员，不改变已有项目单价。此原型不保存密码，也不模拟真实认证。</div>${footer()}`;}
function renderAbout(){return heading('关于这个作品','以外包项目协作为场景，探索复杂业务规则如何转化为清晰的交互。',btn('开始交互体验','guide','primary','play'),'PORTFOLIO / CASE STUDY')+`<section class="about-hero"><div class="eyebrow">NEXUS / 协作工时</div><h2>从一条工作日志，<br>连接整个项目的投入与协作。</h2><p>面向外包人员、外包项目经理、银行项目经理和管理员的项目管理交互原型。围绕“工时是否准确、预算是否可控、确认是否有效”三个问题，将分散的填报、核对、确认和报告整合为可体验的业务流程。</p><span class="callout-tag">虚构场景 · 交互原型 · 2026</span></section><div class="about-grid"><section class="panel about-card"><div class="eyebrow">01 / INFORMATION DESIGN</div><h3>把复杂信息变得可读</h3><p>以项目为主线连接人员、日志与预算。在总览中定位风险，在详情中追溯来源。</p><ul class="feature-list"><li>区分实际投入与已确认投入</li><li>展示预算使用率与未确认风险</li><li>图表、表格与状态标签统一表达</li></ul></section><section class="panel about-card"><div class="eyebrow">02 / BUSINESS INTERACTION</div><h3>业务规则融入操作</h3><p>通过角色与前置条件，让每个确认动作都有明确的责任人与数据范围。</p><ul class="feature-list"><li>日常 → 月度 → 整体逐级确认</li><li>产生日志后锁定项目单价</li><li>数据变化后使旧确认失效</li></ul></section><section class="panel about-card"><div class="eyebrow">03 / FRONTEND PROTOTYPE</div><h3>轻量而完整的体验</h3><p>此展示版使用 HTML、CSS 和原生 JavaScript 实现，支持浏览器本地保存和离线运行。</p><ul class="feature-list"><li>响应式布局与键盘操作</li><li>CSV 导入导出与报告打印</li><li>一键切换身份与重置样例</li></ul></section></div><section class="panel section-gap"><div class="panel-head"><h2>体验路径与实现边界</h2></div><div class="panel-body"><div class="step-list">${['填报日志','日常确认','月度确认','整体确认','报告预览'].map((v,i)=>`<div class="step done"><div class="step-circle">${i+1}</div>${v}</div>`).join('')}</div><p class="note-paragraph">当前页面是面向作品展示的独立前端演示，不连接银行内网或真实账号，数据与机构名称均为虚构。原工程交付采用 React 类组件、Ant Design 3 与 Dva；本展示版为可离线运行的独立重构，不能代表已完成生产部署或真实接口联调。</p><p class="note-paragraph">演示日期固定为 2026 年 10 月 29 日。业务数据以浏览器本地存储保存；CSV 为原型替代格式，报告提供 HTML 预览与浏览器打印，尚未实现正式方案中的 Excel 文件处理、固定 Word 模板、服务端认证与并发一致性。</p><div class="actions section-gap">${btn('重置全部演示数据','reset-demo','','refresh')}${btn('体验完整流程','guide','primary','play')}</div></div></section>${footer()}`;}
function openModal(title,subtitle,body,foot='',wide=false){session.modalTrigger=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="close" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</section></div>`;requestAnimationFrame(()=>$('.modal button, .modal input, .modal select')?.focus());}
function closeModal(){const root=$('#modal-root');if(root.innerHTML){root.innerHTML='';session.modalTrigger?.focus?.();}}
function showGuide(){const p=project('p4'),a=aggregate(p),stages=[a.logs.some(l=>l.user==='u1'&&l.date===TODAY),a.logs.length&&a.logs.every(l=>l.daily),a.logs.length&&a.logs.every(l=>l.monthly),!!p.confirmedAt,!!p.confirmedAt];openModal('一分钟，体验一条日志的完整旅程','使用专门的演示项目「客户服务知识库」，操作结果会在各页面联动。',`<div class="guide-intro"><div class="eyebrow">A CONNECTED WORKFLOW</div><h3>切换身份，换个视角看协作。</h3><p>不需要注册或登录。点击每一步的体验按钮，会自动切换到对应身份和页面。完成后再打开本指南继续下一步。</p></div>${[['吴晨 · 外包开发人员','填写一条 8 小时日志，观察项目实际投入变化。','guide-log'],['陈嘉宁 · 外包项目经理','检查今天的日志，勾选并执行日常确认。','guide-daily'],['林知远 · 银行项目经理','核对当月全部日志，执行月度确认。','guide-monthly'],['林知远 · 银行项目经理','复核工时、金额与考勤差异，确认整体工作量。','guide-overall'],['项目报告','查看基于当前有效确认生成的报告，支持打印。','guide-report']].map(([title,desc,act],i)=>`<div class="guide-item"><span class="guide-number">${stages[i]?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${title}</strong><p>${desc}</p></div>${btn(stages[i]?'再次查看':'去体验',act,i===stages.findIndex(s=>!s)?'primary small':'small','arrow')}</div>`).join('')}<p class="annotation">需要重新开始时，可在“关于作品”中重置演示数据。</p>`);}
function openLog(id=null){const existing=id?db.logs.find(l=>l.id===id):null;if(existing&&existing.user!==user().id)return toast('仅原填报人可修改日志',true);if(user().type!=='EXTERNAL'||user().status!=='ACTIVE')return toast('请切换到启用的外包人员身份',true);const eligible=db.projects.filter(p=>p.status==='ACTIVE'&&member(p.id,user().id)?.status==='ACTIVE');if(!eligible.length&&!existing)return toast('当前没有可填报的参与中项目',true);session.editLog=id;const preferred=existing?.project||(session.guide?'p4':eligible[0]?.id);const p=project(preferred);openModal(existing?'修改工作日志':'记录今天的工作',existing?'修改后将重置日常、月度确认及项目整体确认。':'按项目填写实际工作内容与工时，金额由项目单价自动计算。',`<form id="log-form"><div class="form-grid"><div class="field full"><label for="entry-project">所属项目</label><select id="entry-project" name="project" ${existing?'disabled':''}>${(existing?[p]:eligible).map(p=>option(p.id,p.name,preferred)).join('')}</select></div><div class="field"><label for="entry-date">工作日期</label><input type="date" id="entry-date" name="date" max="${TODAY}" value="${existing?.date||TODAY}" required ${existing?'disabled':''}></div><div class="field"><label for="entry-hours">耗费工时（小时）</label><input type="number" id="entry-hours" name="hours" value="${existing?.hours||8}" min="0.5" step="0.5" required></div><div class="field full"><label for="entry-content">工作内容</label><textarea id="entry-content" name="content" placeholder="记录完成的任务、产出或遇到的问题…" maxlength="2000" required>${h(existing?.content||(session.guide?'完成知识库检索页面开发，完善关键词搜索、空状态与加载反馈。':''))}</textarea></div></div><div class="info-strip section-gap">${icon('info')}填报人：${h(user().name)}。同一人员、项目、日期仅允许一条日志；日期不晚于演示日期 2026-10-29。</div><div class="modal-foot" style="padding:18px 0 0">${btn('取消','close-modal')}<button class="btn primary" type="submit">${icon('check')}${existing?'保存修改':'保存日志'}</button></div></form>`);session.guide=false;}
function projectForm(id=null){const p=id?project(id):null;if(p&&!canEdit(p))return toast('当前身份无权修改此项目',true);if(!manager())return toast('项目经理或管理员才能登记项目',true);session.editProject=id;session.draftMembers=p?structuredClone(db.members.filter(m=>m.project===id)):[];const companies=[...new Set(db.users.filter(u=>u.company).map(u=>u.company))];const company=p?.company||companies[0];if(!p)session.draftMembers=[newDraftMember(company)];openModal(p?'修改项目':'登记新项目',p?'项目进度由系统维护；产生日志后项目单价锁定。':'登记基本信息与成员预计投入，自动测算工作量及预算。',`<form id="project-form"><div class="form-grid"><div class="field"><label for="form-project-name">项目名称</label><input id="form-project-name" name="name" required maxlength="100" value="${h(p?.name||'')}" placeholder="例如：客户服务知识库"></div><div class="field"><label for="form-project-no">需求编号</label><input id="form-project-no" name="no" required maxlength="64" value="${h(p?.no||'')}" placeholder="PRD-2026-007"></div><div class="field"><label for="form-company">合作公司</label><select id="form-company" name="company" ${p&&session.draftMembers.length?'disabled':''}>${companies.map(c=>option(c,c,company)).join('')}</select></div><div class="field"><label for="form-due">计划完成日期</label><input id="form-due" name="due" type="date" required value="${p?.due||'2026-12-01'}"></div><div class="field"><label for="form-bank">银行项目经理</label><select id="form-bank" name="bank">${db.users.filter(u=>u.role==='BANK_MANAGER'&&u.status==='ACTIVE').map(u=>option(u.id,u.name,p?.bank||'b1')).join('')}</select></div><div class="field"><label for="form-vendor">外包项目经理</label><select id="form-vendor" name="vendor">${vendorOptions(company,p?.vendor)}</select></div></div><h3 class="section-title section-gap">成员与预算</h3><p class="annotation">预算 = 各成员预计工时 × 项目约定单价；移除成员保留预计投入与历史日志。</p><div class="member-scroll section-gap" id="draft-members">${draftRows(company,p)}</div><div class="actions">${!p||canBudget(p)?btn('添加成员','add-member','small','plus'):''}</div><div id="draft-total" class="info-strip section-gap">${draftTotal()}</div><div class="modal-foot" style="padding:18px 0 0">${btn('取消','close-modal')}<button class="btn primary" type="submit">保存项目</button></div></form>`,'',true);}
function vendorOptions(company,selected){return db.users.filter(u=>u.role==='VENDOR_MANAGER'&&u.company===company&&u.status==='ACTIVE').map(u=>option(u.id,u.name,selected)).join('');}
function newDraftMember(company){const used=new Set(session.draftMembers.map(m=>m.user));const u=db.users.find(u=>u.type==='EXTERNAL'&&u.company===company&&u.status==='ACTIVE'&&!used.has(u.id));return u?{id:uid(),user:u.id,level:u.level,rate:u.rate,hours:40,status:'ACTIVE',project:session.editProject||null}:null;}
function draftRows(company,p){session.draftMembers=session.draftMembers.filter(Boolean);const editable=!p||canBudget(p);return`<div class="member-row member-head"><span>项目成员</span><span>约定等级</span><span>预计工时 h</span><span>单价 元/h</span><span>预算金额 元</span><span>操作</span></div>${session.draftMembers.map((m,i)=>{const exists=db.members.some(x=>x.id===m.id),locked=db.logs.some(l=>l.project===p?.id&&l.user===m.user),u=person(m.user);return`<div class="member-row ${m.status==='REMOVED'?'row-removed':''}"><select aria-label="第 ${i+1} 行项目成员" data-member="${i}" data-key="user" ${exists||!editable?'disabled':''}>${db.users.filter(u=>u.type==='EXTERNAL'&&u.company===company&&(u.status==='ACTIVE'||u.id===m.user)).map(u=>option(u.id,u.name,m.user)).join('')}</select><select aria-label="${h(u.name)}等级" data-member="${i}" data-key="level" ${!editable?'disabled':''}>${Object.entries(levelNames).map(([v,l])=>option(v,l,m.level)).join('')}</select><input aria-label="${h(u.name)}预计工时" type="number" min="0" step="0.5" value="${m.hours}" data-member="${i}" data-key="hours" required ${!editable?'disabled':''}><input aria-label="${h(u.name)}项目单价${locked?'（已锁定）':''}" title="${locked?'已有日志，项目单价锁定':'项目约定单价'}" type="number" min="0.01" step="0.01" value="${m.rate}" data-member="${i}" data-key="rate" required ${locked||!editable?'disabled':''}><span class="row-status" data-budget-row="${i}">${n(m.hours*m.rate)} ${locked?icon('lock'):''}</span>${editable?`<button type="button" class="text-btn" data-action="remove-member" data-index="${i}" title="${exists?(m.status==='ACTIVE'?'移除':'恢复'):'删除新行'}" aria-label="${exists?(m.status==='ACTIVE'?'移除':'恢复'):'删除'} ${h(u.name)}">${exists?(m.status==='ACTIVE'?'移除':'恢复'):'×'}</button>`:'<span>—</span>'}</div>`;}).join('')||empty('暂无成员')}`;}
function draftTotal(){return`预计总工时 <strong>${n(total(session.draftMembers.filter(Boolean),'hours'))} 小时</strong> · 预算金额 <strong>${money(session.draftMembers.filter(Boolean).reduce((s,m)=>s+Math.round(m.hours*m.rate*100),0)/100)}</strong>`;}
let pendingAction=null;
function ask(title,subtitle,body,callback,label='确认操作'){pendingAction=callback;openModal(title,subtitle,body,btn('取消','close-modal')+btn(label,'confirm-action','primary','check'));}
function scopeSignature(ls){return JSON.stringify(ls.map(l=>[l.id,l.project,l.user,l.date,l.hours,l.content,l.daily,l.monthly,member(l.project,l.user)?.rate]).sort((a,b)=>a[0].localeCompare(b[0])));}
function approve(kind){const p=project(session.approvalProject),ls=approvalScope(),daily=kind==='daily';if(daily?!canDaily(p):!canMonthly(p))return toast('当前身份无权执行此确认',true);const targets=ls.filter(l=>daily?session.selected.has(l.id)&&!l.daily:!l.monthly);if(!targets.length)return toast('没有待确认的日志',true);if(!daily&&ls.some(l=>!l.daily))return toast('请先完成日常确认',true);const signature=scopeSignature(ls),range=daily?session.date:session.month;ask(daily?'确认所选工作日志':'确认本项目月度日志',`${h(p.name)} · ${h(range)}`,`<div class="info-strip">${icon('info')}此次确认覆盖 ${targets.length} 条日志，共 ${n(total(targets,'hours'))} 小时，金额 ${money(targets.reduce((s,l)=>s+amount(l)/100,0))}。</div><p class="note-paragraph">${daily?'确认表示已核对所选日志的工作内容和实际工时。':'确认覆盖当前项目所选月份全部待确认日志，不限当前分页。已确认日志不会重复累加。'}</p>`,()=>{const current=approvalScope();if((daily?!canDaily(p):!canMonthly(p))||signature!==scopeSignature(current)||(daily?session.date:session.month)!==range){toast('数据或范围已变化，请重新核对后确认',true);return;}for(const l of targets){if(daily)l.daily=true;else l.monthly=stamp();}invalidate(p);session.selected.clear();persist(`${p.name}：完成${daily?'日常':'月度'}确认 ${targets.length} 条`);toast(`${daily?'日常':'月度'}确认完成，项目汇总已更新`);});}
function overallConfirm(id){const p=project(id);if(!canMonthly(p))return toast('仅本项目银行经理可整体确认',true);const block=confirmationBlock(p);if(block)return toast(block,true);if(p.confirmedAt)return toast('项目已经整体确认');const signature=JSON.stringify([aggregate(p),db.attendance]);const ws=warnings(p),aws=attendanceWarnings(p);ask('复核并确认项目整体工作量',`${h(p.name)} · 此操作开放项目报告预览`,`<div class="info-strip">${icon('approve')}确认对象：${n(aggregate(p).hours)} 小时 / ${money(aggregate(p).actual)}，覆盖项目全部现有日志。</div>${ws.length||aws.length?`<div class="info-strip amber">${icon('alert')}仍有 ${ws.length} 项项目预警、${aws.length} 项人员月度考勤异常。请核实后确认；超限和考勤差异本身不禁止整体确认。</div>`:''}<p class="note-paragraph">确认后新增或修改日志、调整成员预计投入以及相关考勤变动，会使本次确认失效。付款状态独立保留。</p>`,()=>{if(!canMonthly(p)||confirmationBlock(p)||signature!==JSON.stringify([aggregate(p),db.attendance]))return toast('项目数据已变化，请重新核对',true);p.confirmedAt=stamp();p.confirmedBy=user().id;persist(`${p.name}：整体工作量已确认`);toast('整体工作量已确认，可以预览项目报告');},'已复核，确认工作量');}
function reportHtml(p){const a=aggregate(p);return`<article class="report"><div class="report-label">NEXUS / PROJECT WORKLOAD REPORT</div><h1>${h(p.name)}<br><span style="font-size:18px;color:#87987d">项目工作量报告 · 演示预览</span></h1>${detailKey(p)}<h3>01 / 工作量与金额</h3><table><thead><tr><th>指标</th><th>预计 / 预算</th><th>实际投入</th><th>已月度确认</th><th>差异</th></tr></thead><tbody><tr><td>工时（小时）</td><td>${n(a.estimated)}</td><td>${n(a.hours)}</td><td>${n(a.confirmedHours)}</td><td>${n(a.hours-a.estimated)}</td></tr><tr><td>金额（元）</td><td>${money(a.budget)}</td><td>${money(a.actual)}</td><td>${money(a.confirmedAmount)}</td><td>${money(a.actual-a.budget)}</td></tr></tbody></table><h3>02 / 项目成员与计价</h3><table><thead><tr><th>姓名</th><th>等级</th><th>预计工时 h</th><th>约定单价 元/h</th><th>实际工时 h</th><th>实际金额 元</th></tr></thead><tbody>${a.members.map(m=>{const ls=a.logs.filter(l=>l.user===m.user);return`<tr><td>${h(person(m.user).name)}</td><td>${levelNames[m.level]}</td><td>${n(m.hours)}</td><td>${money(m.rate)}</td><td>${n(total(ls,'hours'))}</td><td>${money(ls.reduce((s,l)=>s+amount(l)/100,0))}</td></tr>`;}).join('')}</tbody></table><h3>03 / 工作日志明细</h3><table><thead><tr><th>日期</th><th>人员</th><th>工作内容</th><th>工时 h</th><th>金额 元</th></tr></thead><tbody>${a.logs.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(l=>`<tr><td>${h(l.date)}</td><td>${h(person(l.user).name)}</td><td class="log-content">${h(l.content)}</td><td>${n(l.hours)}</td><td>${money(amount(l)/100)}</td></tr>`).join('')}</tbody></table><h3>04 / 风险与确认信息</h3>${warnList(p)}${attendanceWarnings(p).map(c=>`<p class="note-paragraph">${h(person(c.user).name)}：${c.missing?'相关日期存在考勤缺失':'月度工时差异 '+n(c.diff)+' 小时'}</p>`).join('')}<p class="note-paragraph">整体确认人：${h(person(p.confirmedBy).name)}<br>整体确认时间：${h(p.confirmedAt)}<br>付款状态：${p.paid?'已付款':'未付款'}<br>本报告基于当前浏览器的虚构演示数据，不作为真实结算凭证。</p></article>`;}
function showReport(id){const p=project(id);if(!manager())return toast('当前身份无报告查看与导出权限',true);if(!p.confirmedAt||confirmationBlock(p))return toast('请先完成当前有效的整体工作量确认',true);openModal('项目报告预览','报告使用当前演示数据，可通过浏览器打印保存为 PDF。',reportHtml(p),btn('关闭','close-modal')+btn('打印 / 保存 PDF','print-report','primary','print',`data-id="${p.id}"`),true);}
function downloadCsv(filename,rows){const escapeCsv=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return'"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\ufeff'+rows.map(row=>row.map(escapeCsv).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前筛选范围的全部数据');}
function exportData(type){if(!manager())return toast('外包人员无导出权限',true);const meta=[['NEXUS 协作工时 · 虚构演示数据'],['演示日期',TODAY],['导出身份',user().name,roleNames[user().role]]];let rows=[],title='业务数据';if(type==='dashboard'||type==='projects'||type==='detail'){const ps=type==='detail'?[project(session.project)]:type==='projects'?filteredProjects():db.projects;title=type==='dashboard'?'项目概览':'项目数据';rows=[...meta,['关键词',session.query||'全部'],['公司',session.company||'全部'],['状态筛选',session.status||'全部'],['需求编号','项目名称','公司','银行经理','外包经理','进度 %','预计工时 h','实际工时 h','已确认工时 h','预算 元','实际金额 元','已确认金额 元','付款状态','整体确认','预警']];for(const p of ps){const a=aggregate(p);rows.push([p.no,p.name,p.company,person(p.bank).name,person(p.vendor).name,p.progress,a.estimated,a.hours,a.confirmedHours,a.budget,a.actual,a.confirmedAmount,p.paid?'已付款':'未付款',p.confirmedAt?'已确认':'未确认',warnings(p).map(w=>w.title+'：'+w.text).join('；')]);}}else if(type==='attendance'){title='工时核对';let cs=checks(session.month).filter(c=>(!session.query||[person(c.user).name,person(c.user).company].join(' ').includes(session.query))&&(!session.checkStatus||(session.checkStatus==='warning'?c.warning:!c.warning)));rows=[...meta,['月份',session.month],['关键词',session.query||'全部'],['状态筛选',session.checkStatus||'全部'],['人员','公司','月份','跨项目日志工时 h','考勤工时 h','差值 h','核对结果']];for(const c of cs)rows.push([person(c.user).name,person(c.user).company,session.month,c.hours,c.attendance,c.diff,c.missing?'考勤缺失':c.warning?'工时差异':'通过']);}else{title='工作日志';const ls=type==='approval'?approvalScope():type==='detail-logs'?aggregate(project(session.project)).logs:filteredLogs();rows=[...meta,['查询范围',type==='approval'?project(session.approvalProject).name:type==='detail-logs'?project(session.project).name:session.query||'全部'],['月份或日期',type==='approval'?(canDaily(project(session.approvalProject))?session.date:session.month):type==='detail-logs'?'全部':session.month||'全部'],['人员范围',type==='logs'&&session.onlyOwn?user().name:'全部'],['项目','日期','姓名','工作内容','工时 h','项目约定单价 元/h','金额 元','日常确认','月度确认']];for(const l of ls)rows.push([project(l.project).name,l.date,person(l.user).name,l.content,l.hours,member(l.project,l.user).rate,amount(l)/100,l.daily?'已确认':'未确认',l.monthly?'已确认':'未确认']);}downloadCsv(title+'_'+TODAY+'.csv',rows);}
function showCheckDetail(id){const u=person(id),ls=db.logs.filter(l=>l.user===id&&l.date.startsWith(session.month)),as=db.attendance.filter(a=>a.user===id&&a.date.startsWith(session.month));const dates=[...new Set([...ls.map(l=>l.date),...as.map(a=>a.date)])].sort();openModal('月度工时明细',`${h(u.name)} · ${h(session.month)} · 按日跨项目汇总`, `<div class="info-strip">${icon('info')}同一人员的多个项目日志先按日合计，再与当日有效考勤对比。考勤缺失和工时差异分别标注。</div><div class="table-scroll"><table><thead><tr><th>日期</th><th>日志工时 h</th><th>考勤工时 h</th><th>差值 h</th><th>核对情况</th></tr></thead><tbody>${dates.map(date=>{const hours=total(ls.filter(l=>l.date===date),'hours'),a=as.find(a=>a.date===date),diff=hours-(a?.hours||0);return`<tr><td>${date}</td><td>${n(hours)}</td><td>${a?n(a.hours):'—'}</td><td>${n(diff)}</td><td>${pill(!a?'考勤缺失':diff?'工时差异':'通过',!a||diff?'amber':'')}</td></tr>`;}).join('')}</tbody></table></div>${!dates.length?empty():''}`,'',true);}
function showImport(){if(user().role!=='SUPER_ADMIN')return toast('仅管理员可导入考勤',true);openModal('导入演示考勤 CSV','原型使用 CSV 格式；按人员、公司和日期新增或覆盖。',`<div class="upload-area">${icon('upload')}<h3>选择 UTF-8 编码的 CSV 文件</h3><p>字段：人员姓名、外包公司、考勤日期、有效工时<br>日期格式 YYYY-MM-DD，工时为 0～24 的数值</p><input type="file" accept=".csv,text/csv" id="attendance-file" aria-label="选择考勤 CSV 文件"></div><div class="actions section-gap">${btn('下载填写模板','attendance-template','','download')}</div><div class="info-strip amber section-gap">${icon('alert')}导入前会整批校验，任一行有误则全部不写入。有效变更会使相关项目整体确认失效。</div><div id="import-result" role="status"></div>`);}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV 引号未闭合');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;}
const validDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s+'T00:00:00Z'))&&new Date(s+'T00:00:00Z').toISOString().slice(0,10)===s;
async function importAttendance(file){if(user().role!=='SUPER_ADMIN')return toast('仅管理员可导入',true);if(!file)return;if(file.size>1024*1024)return toast('请使用小于 1 MB 的 CSV 文件',true);try{const text=await file.text(),rows=parseCsv(text.replace(/^\uFEFF/,''));if(rows.length<2)throw Error('文件没有数据行');if(JSON.stringify(rows[0].map(s=>s.trim()))!==JSON.stringify(['人员姓名','外包公司','考勤日期','有效工时']))throw Error('表头应为：人员姓名、外包公司、考勤日期、有效工时');const batch=[],keys=new Set();for(let i=1;i<rows.length;i++){const values=rows[i].map(s=>s.trim());if(values.length!==4)throw Error(`第 ${i+1} 行列数不正确`);const [name,company,date,raw]=values;const matches=db.users.filter(u=>u.name===name&&u.company===company&&u.type==='EXTERNAL'&&u.status==='ACTIVE');if(matches.length!==1)throw Error(`第 ${i+1} 行无法唯一匹配启用的外包人员`);if(!validDate(date))throw Error(`第 ${i+1} 行日期无效`);const hours=Number(raw);if(raw===''||!Number.isFinite(hours)||hours<0||hours>24)throw Error(`第 ${i+1} 行有效工时应为 0～24 的数值`);const key=matches[0].id+'_'+date;if(keys.has(key))throw Error(`第 ${i+1} 行人员与日期重复`);keys.add(key);batch.push({user:matches[0].id,date,hours});}const signature=JSON.stringify(db.attendance);ask('校验通过，确认导入？',`共 ${batch.length} 行有效日考勤`,`<p class="note-paragraph">人员、公司、日期与工时校验通过。重复的人员日期记录将覆盖；相关项目整体确认将重置。</p>`,()=>{if(user().role!=='SUPER_ADMIN'||signature!==JSON.stringify(db.attendance))return toast('数据或权限已变化，请重新导入',true);const affected=new Set();for(const item of batch){const prior=db.attendance.find(a=>a.user===item.user&&a.date===item.date);if(!prior||prior.hours!==item.hours){db.logs.filter(l=>l.user===item.user&&l.date.startsWith(item.date.slice(0,7))).forEach(l=>affected.add(l.project));if(prior)prior.hours=item.hours;else db.attendance.push(item);}}affected.forEach(id=>invalidate(project(id)));persist(`导入日考勤 ${batch.length} 条`);toast(`已导入 ${batch.length} 条，月度核对结果已重算`);},'确认导入');}catch(e){$('#import-result').innerHTML=`<p class="error-text">${h(e.message)}。未写入任何数据。</p>`;toast(e.message,true);}}
function openUser(id=null){if(user().role!=='SUPER_ADMIN')return toast('仅管理员可维护人员',true);const u=id?person(id):null;openModal(u?'维护人员':'新增演示人员','本原型仅维护业务属性，不创建真实登录账号。',`<form id="user-form" data-id="${id||''}"><div class="form-grid"><div class="field"><label for="user-name">姓名</label><input id="user-name" name="name" required maxlength="30" value="${h(u?.name||'')}"></div><div class="field"><label for="user-no">人员编号</label><input id="user-no" name="no" required maxlength="40" value="${h(u?.no||'')}"></div>${!u||u.type==='EXTERNAL'?`<div class="field"><label for="user-company">外包公司</label><input id="user-company" name="company" required value="${h(u?.company||'华辰科技')}" ${u&&db.members.some(m=>m.user===u.id)?'disabled':''}></div><div class="field"><label for="user-level">默认等级</label><select name="level" id="user-level">${Object.entries(levelNames).map(([v,l])=>option(v,l,u?.level||'MIDDLE')).join('')}</select></div><div class="field"><label for="user-rate">默认单价（元/小时）</label><input id="user-rate" name="rate" type="number" min="0.01" step="0.01" required value="${u?.rate||300}"></div>`:''}<div class="field"><label for="user-status">账号状态</label><select id="user-status" name="status">${option('ACTIVE','启用',u?.status||'ACTIVE')}${option('DISABLED','停用',u?.status||'ACTIVE')}</select></div></div><div class="info-strip section-gap">${icon('info')}${u?'已有成员关系时公司锁定；修改默认单价不会影响任何已存在的项目约定单价。':'新增人员为普通外包人员，可在对应公司项目中添加为成员。'}</div><div class="modal-foot" style="padding:18px 0 0">${btn('取消','close-modal')}<button class="btn primary" type="submit">保存人员</button></div></form>`);}
function saveLog(form){const fd=new FormData(form),existing=session.editLog?db.logs.find(l=>l.id===session.editLog):null;const pid=existing?.project||fd.get('project'),date=existing?.date||fd.get('date'),hours=Number(fd.get('hours')),content=String(fd.get('content')||'').trim(),p=project(pid);if(user().type!=='EXTERNAL'||user().status!=='ACTIVE'||existing&&existing.user!==user().id)return toast('当前身份无权保存',true);if(!validDate(date)||date>TODAY)return toast('工作日期不能晚于演示日期',true);if(!Number.isFinite(hours)||hours<=0||hours*2%1!==0)return toast('工时应为正数且按 0.5 小时填写',true);if(!content||content.length>2000)return toast('请填写有效工作内容，最多 2000 字',true);if(!existing&&(p?.status!=='ACTIVE'||member(pid,user().id)?.status!=='ACTIVE'))return toast('仅允许向参与中的有效项目新增日志',true);if(db.logs.some(l=>l.id!==existing?.id&&l.project===pid&&l.user===user().id&&l.date===date))return toast('同一项目、人员和日期已有日志，请修改已有记录',true);if(existing)Object.assign(existing,{hours,content,daily:false,monthly:null});else db.logs.push({id:uid(),project:pid,user:user().id,date,hours,content,daily:false,monthly:null});invalidate(p);session.month=date.slice(0,7);session.logPage=1;closeModal();persist(`${user().name}：${existing?'修改':'新增'} ${p.name} 工作日志`);toast(existing?'修改已保存，日常、月度和整体确认已重置':'日志已保存，工时、金额与预警已更新');}
function saveProject(form){const fd=new FormData(form),old=session.editProject?project(session.editProject):null;if(!manager()||old&&!canEdit(old))return toast('当前身份无权保存项目',true);const name=String(fd.get('name')||'').trim(),no=String(fd.get('no')||'').trim(),company=old&&session.draftMembers.length?old.company:fd.get('company'),bank=fd.get('bank'),vendor=fd.get('vendor'),due=fd.get('due');if(!name||!no||!validDate(due))return toast('请完整填写基本信息与有效日期',true);if(db.projects.some(p=>p.id!==old?.id&&p.no.toLowerCase()===no.toLowerCase()))return toast('需求编号已存在，请使用唯一编号',true);if(person(bank).role!=='BANK_MANAGER'||person(bank).status!=='ACTIVE'||person(vendor).role!=='VENDOR_MANAGER'||person(vendor).status!=='ACTIVE'||person(vendor).company!==company)return toast('请核对项目经理角色、公司和账号状态',true);const ms=session.draftMembers.filter(Boolean),seen=new Set();for(const m of ms){const u=person(m.user),original=old?member(old.id,m.user):null;if(seen.has(m.user))return toast('同一成员不能重复添加',true);seen.add(m.user);if(u.company!==company||(!original&&u.status!=='ACTIVE'))return toast('成员应属于同一公司，且新成员账号需启用',true);if(!Number.isFinite(m.hours)||m.hours<0||m.hours*2%1!==0||!Number.isFinite(m.rate)||m.rate<=0)return toast('预计工时须非负且按 0.5 小时填写，单价须大于 0',true);if(!Object.hasOwn(levelNames,m.level))return toast('人员等级无效',true);if(original&&db.logs.some(l=>l.project===old.id&&l.user===m.user)&&m.rate!==original.rate)return toast('已有日志的项目单价已锁定',true);}if(old&&!canBudget(old)&&JSON.stringify(ms)!==JSON.stringify(db.members.filter(m=>m.project===old.id)))return toast('当前身份不能修改成员预算',true);const p=old||{id:uid(),progress:0,status:'ACTIVE',paid:false,confirmedAt:null};const oldMs=old?JSON.stringify(db.members.filter(m=>m.project===old.id)):'';Object.assign(p,{name,no,company,bank,vendor,due});if(!old)db.projects.unshift(p);const newMs=ms.map(m=>({...m,project:p.id}));db.members=db.members.filter(m=>m.project!==p.id).concat(newMs);if(oldMs!==JSON.stringify(newMs))invalidate(p);closeModal();session.page='detail';session.project=p.id;session.tab='overview';session.logPage=1;location.hash='detail/'+p.id;persist(`${name}：${old?'更新':'登记'}项目`);toast('项目已保存，预算与预警已重新计算');}
function saveUser(form){if(user().role!=='SUPER_ADMIN')return toast('仅管理员可保存人员',true);const fd=new FormData(form),id=form.dataset.id,old=id?person(id):null,name=String(fd.get('name')||'').trim(),no=String(fd.get('no')||'').trim();if(!name||!no)return toast('请填写姓名和人员编号',true);if(db.users.some(u=>u.id!==id&&u.no===no))return toast('人员编号已存在',true);const type=old?.type||'EXTERNAL',company=type==='EXTERNAL'?(fd.get('company')||old?.company):null,rate=type==='EXTERNAL'?Number(fd.get('rate')):null,level=type==='EXTERNAL'?fd.get('level'):null;if(type==='EXTERNAL'&&(!company||!Number.isFinite(rate)||rate<=0))return toast('请填写公司和有效正单价',true);const u=old||{id:uid(),role:'NONE',type:'EXTERNAL',login:'demo-'+uid().slice(0,8)};Object.assign(u,{name,no,company,rate,level,status:fd.get('status')});if(!old)db.users.push(u);closeModal();persist(`${name}：维护演示人员资料`);toast('人员资料已保存，已有项目单价保持不变');}
const actions={
 nav:e=>nav(e.dataset.page),detail:e=>nav('detail',e.dataset.id),
 'detail-tab':e=>{session.tab=e.dataset.tab;session.logPage=1;render();},
 'project-page':e=>{session.projectPage=Number(e.dataset.page);render();},'log-page':e=>{session.logPage=Number(e.dataset.page);render();},
 'create-project':()=>projectForm(),'edit-project':e=>projectForm(e.dataset.id),'new-log':()=>openLog(),'edit-log':e=>openLog(e.dataset.id),
 'reset-filter':()=>{session.query='';session.company='';session.status='';session.projectPage=1;render();},
 'reset-log-filter':()=>{session.query='';session.month=MONTH;session.onlyOwn=false;session.logPage=1;render();},
 'risk-projects':()=>{nav('projects');session.status='risk';render();},
 'go-daily':()=>{session.user='v1';session.onlyOwn=false;nav('approval');session.date='2026-10-28';render();},
 guide:showGuide,'close-modal':closeModal,'confirm-action':()=>{const fn=pendingAction;pendingAction=null;closeModal();fn?.();},
 'daily-confirm':()=>approve('daily'),'monthly-confirm':()=>approve('monthly'),'overall-confirm':e=>overallConfirm(e.dataset.id),
 'toggle-paid':e=>{const p=project(e.dataset.id);if(!canPaid(p))return toast('当前身份无付款维护权限',true);const paid=p.paid;ask(paid?'标记为未付款？':'标记为已付款？',h(p.name),'<p class="note-paragraph">付款状态独立记录，不改变工时、金额或各级确认状态。</p>',()=>{if(!canPaid(p))return toast('权限已变化，请重试',true);p.paid=!paid;persist(`${p.name}：${p.paid?'已付款':'未付款'}`);toast('付款状态已更新');});},
 report:e=>showReport(e.dataset.id),'print-report':e=>{const p=project(e.dataset.id);if(!manager()||!p.confirmedAt||confirmationBlock(p))return toast('当前报告确认已失效',true);$('#print-root').innerHTML=reportHtml(p);window.print();},
 'export-dashboard':()=>exportData('dashboard'),'export-projects':()=>exportData('projects'),'export-detail':()=>exportData('detail'),'export-detail-logs':()=>exportData('detail-logs'),'export-logs':()=>exportData('logs'),'export-approval':()=>exportData('approval'),'export-attendance':()=>exportData('attendance'),
 'check-detail':e=>showCheckDetail(e.dataset.id),'import-attendance':showImport,
 'attendance-template':()=>downloadCsv('考勤导入模板.csv',[['人员姓名','外包公司','考勤日期','有效工时'],['吴晨','华辰科技',TODAY,8]]),
 'new-user':()=>openUser(),'edit-user':e=>openUser(e.dataset.id),
 'add-member':()=>{const company=$('#form-company').value,p=session.editProject?project(session.editProject):null;if(p&&!canBudget(p))return;const m=newDraftMember(company);if(!m)return toast('该公司暂无未添加的启用人员');session.draftMembers.push(m);$('#draft-members').innerHTML=draftRows(company,p);$('#draft-total').innerHTML=draftTotal();},
 'remove-member':e=>{const p=session.editProject?project(session.editProject):null;if(p&&!canBudget(p))return;const i=Number(e.dataset.index),m=session.draftMembers[i];if(db.members.some(x=>x.id===m.id))m.status=m.status==='ACTIVE'?'REMOVED':'ACTIVE';else session.draftMembers.splice(i,1);$('#draft-members').innerHTML=draftRows($('#form-company').value,p);$('#draft-total').innerHTML=draftTotal();},
 'reset-demo':()=>ask('重置全部演示数据？','这将清除当前浏览器内的演示修改。','<p class="note-paragraph">重置后将恢复虚构项目、日志、成员和考勤样例。已下载的文件不受影响。</p>',()=>{db=seed();session.user='b1';session.month=MONTH;session.date=TODAY;session.page='dashboard';session.tab='overview';session.query='';session.company='';session.status='';session.selected.clear();session.logPage=1;session.projectPage=1;session.onlyOwn=false;session.checkStatus='';location.hash='dashboard';persist();toast('已恢复初始样例，可以重新体验');},'重置演示数据'),
 'guide-log':()=>{session.user='u1';session.onlyOwn=true;nav('logs');session.guide=true;const l=db.logs.find(l=>l.project==='p4'&&l.user==='u1'&&l.date===TODAY);if(l){toast('今天的演示日志已存在，可查看或修改');session.guide=false;}else openLog();},
 'guide-daily':()=>{session.user='v1';session.onlyOwn=false;nav('approval');session.approvalProject='p4';session.date=TODAY;session.logPage=1;render();},
 'guide-monthly':()=>{session.user='b1';session.onlyOwn=false;nav('approval');session.approvalProject='p4';session.month=MONTH;session.logPage=1;render();},
 'guide-overall':()=>{session.user='b1';session.onlyOwn=false;nav('detail','p4');session.tab='settlement';render();},
 'guide-report':()=>{session.user='b1';session.onlyOwn=false;nav('detail','p4');session.tab='settlement';render();showReport('p4');},
 menu:()=>{$('.sidebar').classList.add('open');$('.mobile-overlay').classList.add('show');},'menu-close':()=>{$('.sidebar').classList.remove('open');$('.mobile-overlay').classList.remove('show');}
};
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target&&!target.disabled){const fn=actions[target.dataset.action];if(fn)fn(target);}if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('submit',e=>{const form=e.target;const ids=['project-filter','log-filter','approval-filter','attendance-filter','log-form','project-form','user-form'];if(!ids.includes(form.id))return;e.preventDefault();const fd=new FormData(form);switch(form.id){case'project-filter':session.query=String(fd.get('query')||'').trim();session.company=fd.get('company');session.status=fd.get('status');session.projectPage=1;render();break;case'log-filter':session.query=String(fd.get('query')||'').trim();session.month=fd.get('month');session.onlyOwn=fd.get('scope')==='own';session.logPage=1;render();break;case'approval-filter':session.approvalProject=fd.get('project');if(canDaily(project(session.approvalProject)))session.date=fd.get('range')?.length===10?fd.get('range'):TODAY;else session.month=fd.get('range')?.length===7?fd.get('range'):MONTH;session.selected.clear();session.logPage=1;render();break;case'attendance-filter':session.query=String(fd.get('query')||'').trim();session.month=fd.get('month');session.checkStatus=fd.get('status');render();break;case'log-form':saveLog(form);break;case'project-form':saveProject(form);break;case'user-form':saveUser(form);break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='role-picker'){const u=person(el.value);if(u.status!=='ACTIVE'){toast('该演示账号已停用，请在管理员身份恢复',true);render();return;}session.user=el.value;session.onlyOwn=false;session.selected.clear();session.logPage=1;closeModal();if(session.page==='approval'){const ps=db.projects.filter(p=>canMonthly(p)||canDaily(p));session.approvalProject=(ps[0]||db.projects[0]).id;session.date=user().role==='VENDOR_MANAGER'?'2026-10-28':TODAY;session.month=MONTH;}render();toast(`已切换为${roleNames[user().role]}`);}else if(el.id==='approval-project'){session.approvalProject=el.value;session.selected.clear();session.logPage=1;session.date=user().role==='VENDOR_MANAGER'?'2026-10-28':TODAY;session.month=MONTH;render();}else if(el.id==='select-all'){for(const l of approvalScope().filter(l=>!l.daily)){if(el.checked)session.selected.add(l.id);else session.selected.delete(l.id);}render();}else if(el.dataset.logSelect){el.checked?session.selected.add(el.dataset.logSelect):session.selected.delete(el.dataset.logSelect);render();}else if(el.dataset.member!==undefined){syncDraft(el,true);}else if(el.id==='form-company'){session.draftMembers=[];const m=newDraftMember(el.value);if(m)session.draftMembers.push(m);$('#form-vendor').innerHTML=vendorOptions(el.value);$('#draft-members').innerHTML=draftRows(el.value,null);$('#draft-total').innerHTML=draftTotal();}else if(el.id==='attendance-file')importAttendance(el.files[0]);});
function syncDraft(el,rerender=false){const index=Number(el.dataset.member),key=el.dataset.key,m=session.draftMembers[index];if(!m)return;const p=session.editProject?project(session.editProject):null;if(p&&!canBudget(p))return;if(key==='rate'&&p&&db.logs.some(l=>l.project===p.id&&l.user===m.user))return;if(key==='user'){if(db.members.some(x=>x.id===m.id))return;const u=person(el.value);m.user=u.id;m.rate=u.rate;m.level=u.level;}else m[key]=['hours','rate'].includes(key)?Number(el.value):el.value;if(key==='user'&&rerender)$('#draft-members').innerHTML=draftRows($('#form-company').value,p);else{const cell=$(`[data-budget-row="${index}"]`);if(cell)cell.textContent=n(m.hours*m.rate);}$('#draft-total').innerHTML=draftTotal();}
document.addEventListener('input',e=>{if(e.target.dataset.member!==undefined&&['hours','rate'].includes(e.target.dataset.key))syncDraft(e.target);});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(!modal)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const all=[...modal.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(el=>el.getClientRects().length);if(!all.length)return;if(e.shiftKey&&document.activeElement===all[0]){e.preventDefault();all.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===all.at(-1)){e.preventDefault();all[0].focus();}}});
function readHash(){let hash;try{hash=decodeURIComponent(location.hash.slice(1));}catch{hash='dashboard';}const [page,id]=hash.split('/');if(['dashboard','projects','detail','logs','approval','attendance','accounts','about'].includes(page)){if(page==='detail'&&id&&!project(id)){session.page='projects';return;}session.page=page;if(page==='detail'&&id)session.project=id;}}
window.addEventListener('afterprint',()=>{$('#print-root').innerHTML='';});
window.addEventListener('hashchange',()=>{const before=session.page+'/'+session.project;readHash();if(before!==session.page+'/'+session.project)closeModal();render();});
window.addEventListener('storage',e=>{if(e.key===KEY){closeModal();pendingAction=null;session.selected.clear();try{const changed=JSON.parse(e.newValue);if(changed?.version===1){db=changed;render();toast('其他标签页更新了演示数据，当前页面已同步');}}catch{toast('演示数据读取失败，请刷新页面',true);}}});
if(user().status!=='ACTIVE')session.user='admin';readHash();render();
